package com.stark.automation.pages;
import com.stark.automation.utils.Waits; import org.openqa.selenium.By;
public class CheckoutPage { private final By firstName = By.id("first-name"), lastName = By.id("last-name"), postal = By.id("postal-code"), continueButton = By.id("continue"), error = By.cssSelector("[data-test='error']"); public CheckoutPage continueWithoutDetails() { Waits.clickable(continueButton); com.stark.automation.core.driver.DriverFactory.getDriver().findElement(continueButton).click(); return this; } public CheckoutPage enterDetails(String first, String last, String zip) { Waits.visible(firstName).sendKeys(first); Waits.visible(lastName).sendKeys(last); Waits.visible(postal).sendKeys(zip); return this; } public String errorMessage() { return Waits.visible(error).getText(); } }
